-- Généré par tools/generate_data.py : ne pas éditer à la main.
local locale = GetLocale()
if locale ~= "deDE" then return end
local _, NS = ...
NS.Tactics = NS.Tactics or {}
local T = NS.Tactics
T[1] = { { "Feuernova", "Feuerschaden an allen in seiner Nähe, mehrmals pro Kampf. Als Heiler: Halte den Nahkampf bei vollem Leben." }, { "Aufwärtshaken", "Ein heftiger Schlag, der den Tank wegstößt." } }
T[2] = { { "Feuerbrand", "Verbrennt einen Spieler, dann alle paar Sekunden Feuerschaden für 21 Sekunden. Unterbrich den Zauber oder bann das Brennen." }, { "Fluch der Schwäche", "Verringert den körperlichen Schaden eines Spielers für 30 Sekunden. Ein Magier oder Druide kann ihn entfernen." } }
T[3] = { { "Spalten", "Trifft sein Ziel und den Spieler, der ihm am nächsten steht." } }
T[4] = { { "Gift", "Seine Schläge vergiften: Naturschaden über Zeit. Heile das Gift, wenn du kannst." }, { "Heimtückischer Angriff", "Zusätzlicher Schaden auf den Tank alle 5 bis 15 Sekunden." } }
T[5] = { { "Flüche und Krankheiten", "Etwas, das einen Fluch aufhebt oder eine Krankheit heilt, hilft sehr. Sonst ein leichter Kampf: Säubere den Raum, bevor du ihn angehst." } }
T[6] = { { "Der Beschwörer", "Töte zuerst den Beschwörer: Er ruft Verstärkung. Danach den Elementar." }, { "Feuer überall", "Flächenschaden auf die Gruppe, schlimmer, wenn die Gruppe viel im Nahkampf kämpft." } }
T[7] = { { "Quer durch den Raum geschleudert", "Er schleudert Spieler quer durch den Raum. Säubere die nächsten Gruppen und tanke ihn nahe am Tunnel, damit niemand in einer anderen Gruppe landet." } }
T[8] = { { "Furcht bei schwindendem Leben", "Wenn sein Leben sinkt, versetzt er die ganze Gruppe in Furcht. Plane etwas ein, um sie zu brechen, oder säubere vorher den Raum, damit niemand in andere Gegner rennt." }, { "Die verschlossenen Gewölbe", "Öffne nach dem Kampf die Gewölbe des Raums: etwa 24 Dwarven Heirlooms für Important Heirlooms und die Tafel von The Treaty of Understanding." } }
T[9] = { { "Die Spinnen im Hof", "Nichts Besonderes am Boss selbst. Säubere zuerst die anderen Spinnen im Hof, sonst schließen sie sich dem Kampf an." } }
T[10] = { note = "Säubere den Hof, klick auf die Statue und halte während der Wellen durch: Sie kommt danach.", { "Frostnova", "Frostschaden auf die ganze Gruppe. Wenn du heilst, spar Mana für alle Wellen." } }
T[11] = { { "In die Luft geschleudert", "Schleudert den Tank in die Luft und betäubt ihn 5 Sekunden lang. Achte als Schadensverursacher auf die Bedrohung: Der Tank hält ihn nur etwa den halben Kampf." }, { "Eine Patrouille", "Säubere seinen Raum, bevor du ihn angehst: Eine Patrouille kommt dort vorbei. Sein Kopf wird für die Quests Abominable Creatures und Unending Torment aufgesammelt." } }
T[12] = { { "Flammenschock", "Sein Hauptzauber. Er kann unterbrochen und betäubt werden: Koordiniere Unterbrechungen und Betäubungen mit der Gruppe." }, { "Viele Lebenspunkte", "Der längste Kampf des Dungeons. Unterbrich bis zum Schluss weiter." } }
T[13] = { note = "Säubere das Haus und die Statue, klick auf den Kamin und halte während der Wellen durch. Er kommt nach dem letzten Fleischgolem.", { "Gift", "Vergiftet sein Ziel. Behalte die Lebensbalken im Auge." }, { "Kräftige Schläge", "Er haut hart zu: Halte den Tank am Leben. Plane Manatränke für die Wellen vor ihm ein." } }
T[14] = { { "Zurückstoßen", "Er stößt zurück: Säubere zuerst die Gruppen um ihn herum, sonst landest du in einer davon." }, { "Antimagieschild", "Schützt sich eine Weile vor Zaubern." }, { "Kräftige Schläge", "Er haut hart zu: Halte den Tank bei vollem Leben." } }
T[15] = { { "Blitzschlag", "Er hält Abstand, um ihn zu wirken. Unterbrich ihn." }, { "Heilende Berührung", "Heilt sich oder einen Verbündeten (3 Sekunden Zauberzeit). Unterbrich ihn." }, { "Cobrahns Schlangengestalt", "Bei 30 % Leben verwandelt er sich in eine Schlange: langsamere, aber schwerere Schläge, und er beginnt, Spieler einzuschläfern." } }
T[16] = { { "Heilende Berührung", "Heilt sich oder einen Verbündeten. Unterbrich sie." }, { "Schlaf", "Versetzt einen Spieler bis zu 20 Sekunden lang in Schlaf. Schaden weckt ihn, und Magie bannen entfernt ihn." }, { "Dornenaura", "Naturschaden an jedem, der sie im Nahkampf schlägt." } }
T[17] = { { "Panzerschild", "12 Sekunden lang erleidet er 60 % weniger Schaden und greift langsamer, aber härter an." } }
T[18] = { { "Donnerschlag", "Naturschaden an allen in seiner Nähe, dann 10 Sekunden lang verlangsamte Angriffe und Bewegungen." }, { "Heilende Berührung", "Heilt sich oder einen Verbündeten. Unterbrich ihn." }, { "Schlaf", "Versetzt einen Spieler bis zu 20 Sekunden lang in Schlaf." } }
T[19] = { { "Kettenblitz", "Ein Blitz, der auf einen zweiten Spieler überspringt. Unterbrich ihn." } }
T[20] = { { "Heilende Berührung", "Eine langsame Heilung (3,5 Sekunden) auf sich oder einen Verbündeten. Unterbrich ihn." }, { "Schlaf", "Versetzt einen Spieler bis zu 20 Sekunden lang in Schlaf." }, { "Blitzschlag", "Er hält Abstand, um ihn zu wirken. Unterbrich ihn." } }
T[21] = { { "Packende Ranken", "Wenn sein Ziel nah ist, wirft er alle in seiner Nähe um und hält sie 10 Sekunden lang fest. Bleib auf Abstand, wenn du weit weg bist." } }
T[22] = { note = "Töte Lady Anacondra, Lord Cobrahn, Lord Pythas und Lord Serpentis, sprich dann am Eingang mit Naralex' Schüler und eskortiere ihn zu Naralex. Beschütze ihn während des Rituals: Mutanus kommt am Ende.", { "Donnerknall", "Naturschaden an allen in seiner Nähe und eine Betäubung von 2,5 Sekunden." }, { "Naralex' Alptraum", "Versetzt einen Spieler bis zu 15 Sekunden lang in Schlaf." }, { "Schrecken", "Lässt einen Spieler 4 Sekunden lang in Furcht fliehen." } }
T[23] = { { "Rhahk'Zors Schlag", "Schlägt den Tank hart und betäubt ihn 3 Sekunden lang." } }
T[24] = { { "Rüstung durchbohren", "Verringert die Rüstung des Tanks 20 Sekunden lang um 75 %." }, { "Flieht um Hilfe", "Bei 15 % Leben flieht er, um Hilfe zu holen. Erledige ihn, bevor er sich entfernt." } }
T[25] = { note = "Er steuert Sneeds Schredder und steigt aus, wenn dieser zerstört wird.", { "Entwaffnen", "Entwaffnet den Tank für 6 Sekunden." } }
T[26] = { { "Schrecken", "Lässt einen Spieler 4 Sekunden lang in Furcht fliehen." }, { "Lähmender Schmerz", "Verlangsamt das Zaubern eines Spielers 15 Sekunden lang um 35 %." } }
T[27] = { { "Geschmolzenes Metall", "Feuerschaden alle 3 Sekunden für 15 Sekunden, mit verlangsamten Angriffen und Bewegungen. Unterbrich die Zauberzeit von 2 Sekunden." } }
T[28] = { { "Heftiges Stampfen", "Bei 66 % und dann bei 33 % Leben betäubt er alle um sich herum und geht dann zu seiner Truhe, um die Waffen zu wechseln." }, { "Verprügeln", "Mit seinen zwei Äxten, ab 66 % Leben: zusätzliche Angriffe auf den Tank." }, { "Mächtiger Schlag", "Mit seinem Hammer, unter 33 % Leben: ein heftiger Schlag, der den Tank 3 Sekunden lang betäubt." } }
T[29] = { { "Vergifteter Harpunenspeer", "Eine Zauberzeit von 2 Sekunden: ein Treffer, dann eine Minute lang Naturschaden. Heile das Gift." }, { "Spalten", "Trifft sein Ziel und den Spieler, der ihm am nächsten steht." } }
T[30] = { { "Zweimal zuschlagen", "Gelegentlich zwei Zusatzangriffe: harte Treffer auf den Tank." }, { "VanCleefs Verbündete", "Bei der Hälfte seines Lebens ruft er zwei Defias-Schurken." } }
T[31] = { { "Säurespritzer", "Naturschaden alle 5 Sekunden für 30 Sekunden an allen in seiner Nähe." }, { "Kochkünste", "Unter der Hälfte seines Lebens heilt er sich (2 Sekunden Zauberzeit). Unterbrich ihn." }, { "Flieht um Hilfe", "Bei 15 % Leben flieht er, um Hilfe zu holen. Erledige ihn, bevor er sich entfernt." } }
T[32] = { { "Seelenentzug", "Hält einen Spieler 10 Sekunden lang fest und entzieht ihm Leben, um sich zu heilen. Unterbrich die Zauberzeit von 2 Sekunden oder bann ihn." } }
T[33] = { { "Verdrehter Schlag", "Das Teufelsross betäubt alle in seiner Nähe für 3 Sekunden, und sie erleiden mehr körperlichen Schaden. Das Schattenross hat keine Fähigkeit." } }
T[34] = { { "Entzug des Schlächters", "Entzieht seinem Ziel im Nahkampf 350 Mana: Ein Tank mit Mana spürt es." } }
T[35] = { { "Schleier der Schatten", "Verflucht einen Spieler: Die Heilung, die er erhält, ist 15 Sekunden lang um 75 % schwächer. Entferne ihn, vor allem beim Tank." } }
T[36] = { { "Heiliges Licht", "Heilt sich oder einen Verbündeten (2,5 Sekunden Zauberzeit). Unterbrich ihn." }, { "Gottesschild", "Macht ihn 10 Sekunden lang immun gegen allen Schaden und alle Zauber." }, { "Hammer der Gerechtigkeit", "Betäubt einen Spieler für 4 Sekunden." } }
T[37] = { { "Ruft um Hilfe", "Wenn du ihn angreifst, ruft er die Kreaturen im Umkreis von 30 Metern. Säubere vorher die Umgebung." }, { "Heulende Wut", "Bei 60 %, 40 % und 20 % Leben werden seine Schläge stärker." } }
T[38] = { { "Spalten", "Trifft sein Ziel und den Spieler, der ihm am nächsten steht." }, { "Kniesehne", "Verlangsamt die Bewegung seines Ziels für 10 Sekunden." } }
T[39] = { note = "Sie kommen zu viert, nachdem Fenrus der Verschlinger gestorben ist: Arugal erscheint kurz und ruft sie.", { "Dunkles Opfer", "Heilt einen anderen Leerwandler. Tötet sie nacheinander." } }
T[40] = { { "Giftiger Speichel", "Naturschaden alle 6 Sekunden und Manaentzug, 2 Minuten lang. Heile das Gift." } }
T[41] = { { "Worgs zur Verstärkung", "Je länger der Kampf dauert, desto mehr Worgs hat er bei sich: nach 30 bis 45 Sekunden ein blasser Worg, dann ein schäumender Worg, dann ein Wolfsschrecken." } }
T[42] = { { "Leerenblitz", "Ein 3 Sekunden langer Schattenblitz auf den Tank, immer wieder. Unterbrich ihn." }, { "Arugals Fluch", "Verwandelt einen Spieler, der nicht der Tank ist, für 10 Sekunden in einen Shadowfang-Vielfraß, der für ihn kämpft. Entferne den Fluch." }, { "Schattenschritt", "Er teleportiert sich zwischen seinem Sims, dem oberen Sims und der Treppe." }, { "Donnerschlag", "Wenn der Tank bei ihm ankommt: Naturschaden und eine Betäubung von 5 Sekunden um ihn herum." } }
T[43] = { { "Zertrampeln", "Trifft alle, die in seiner Nähe stehen." } }
T[44] = { { "Gegabelter Blitz", "Naturschaden in einem Kegel vor ihr (2 Sekunden Zauberzeit). Bleib aus dem Kegel." }, { "Frostnova", "Friert alle in ihrer Nähe bis zu 8 Sekunden lang fest." }, { "Verlangsamen", "Verlangsamt Bewegung und Angriffe eines Spielers für 10 Sekunden." } }
T[45] = { { "Netz", "Hält einen Spieler 10 Sekunden lang an Ort und Stelle fest." } }
T[46] = { note = "Klick auf den Stein der Brasse im Wasser: Er taucht daraus auf.", { "Frostblitz", "Er hält Abstand, um ihn zu wirken: Frostschaden und Verlangsamung." }, { "Frostnova", "Hält alle in seiner Nähe bis zu 8 Sekunden lang fest." } }
T[47] = { { "Schlaf", "Versetzt alle in seiner Nähe bis zu 10 Sekunden lang in Schlaf. Schaden weckt einen Schläfer auf." }, { "Gedankenschlag", "Schattenschaden auf einen Spieler (1,5 Sekunden Zauberzeit)." } }
T[48] = { note = "Er wartet in einer Unterwasserhöhle unter dem Tempel von Twilight Lord Kelris, und viele Gruppen verpassen ihn. Schwimm unter den Tempel, um ihn zu erreichen." }
T[49] = { note = "Sobald Twilight Lord Kelris tot ist, entzünde nacheinander die vier Feuer von Aku'mai in seinem Raum. Jedes bringt eine Welle von Kreaturen. Wenn alle tot sind, öffnet sich Aku'mais Tür.", { "Giftwolke", "Naturschaden alle 5 Sekunden für 45 Sekunden an allen in der Nähe." }, { "Rasende Wut", "Unter 30 % Leben: immer wieder Angriffssalven, die 75 % schneller sind." } }
T[50] = { { "Blitzschild", "Der Blitz trifft jeden, der ihn berührt. Ein Priester oder Schamane kann es entfernen." }, { "Blitzschlag", "Er hält Abstand, um ihn zu wirken. Unterbrich ihn." } }
T[51] = { { "Schildschlag", "Schlägt den Tank und betäubt ihn 2 Sekunden lang." }, { "Flieht um Hilfe", "Bei 15 % Leben flieht er, um Hilfe zu holen. Erledige ihn, bevor er sich entfernt." } }
T[52] = { { "Flieht um Hilfe", "Bei 15 % Leben flieht er, um Hilfe zu holen. Erledige ihn, bevor er sich entfernt." } }
T[53] = { { "Zweimal zuschlagen", "Gelegentlich zwei Zusatzangriffe: harte Treffer auf den Tank." }, { "Wutanfall", "Bei 30 % Leben greift er bis zum Ende des Kampfes 30 % schneller an." } }
T[54] = { { "Kettenblitzschlag", "Ein Blitz, der von Spieler zu Spieler springt (2 Sekunden Zauberzeit). Unterbrich ihn." }, { "Blutrausch", "Beschleunigt seine Angriffe oder die eines Verbündeten 30 Sekunden lang um 30 %. Ein Priester oder Schamane kann ihn entfernen." } }
T[55] = { { "Rauchbombe", "Betäubt alle in seiner Nähe für 4 Sekunden." }, { "Schlachtruf", "Mehr Angriffskraft für ihn und seine Verbündeten für 2 Minuten." }, { "Flieht um Hilfe", "Bei 15 % Leben flieht er, um Hilfe zu holen. Erledige ihn, bevor er sich entfernt." } }
T[56] = { { "Schlag", "Trifft das Ziel mit Waffenschaden plus 5. Halte den Tank am Leben." } }
T[57] = { { "Viel Leben", "Während des Kampfes ist nichts Besonderes aufgefallen: Er schlägt zu und hat viel Leben. Er streift im Anfangssumpf zwischen Elite-Krokilisken umher, räumt sie also zuerst oder zieht ihn von ihnen weg." } }
T[58] = { note = "Tötet die Raptormatriarchin im hohen Gras. Beim Tod kommt eine Welle Raptoren, und Schattenzahn stürmt heran, sobald sie tot sind.", { "Raptoren im Gras", "Kleine Raptoren springen aus dem Gras, wenn ihr hindurchlauft, und lassen euch bluten." }, { "Die Welle vor ihm", "Tötet alle Raptoren der Welle, bevor er eintrifft. Eine Gruppe starb beim ersten Versuch, als Schattenzahn und mehrere Raptoren gleichzeitig auf ihr waren." }, { "Furcht", "Der Tank wird in diesem Kampf mehrmals in Furcht versetzt. Der Totem des Erdstoßes eines Schamanen hilft." } }
T[59] = { note = "Er steht reglos am Ende des Spinnenpfads. Klickt auf das kleine Schild neben ihm, um ihn zu wecken.", { "Bedrohung zurückgesetzt", "Er setzt seine Bedrohung zurück und wechselt im Kampf das Ziel. Schadensverursacher, werdet langsamer, wenn der Tank ihn verliert. Tank, holt ihn sofort zurück." } }
T[60] = { { "Das Drachenmaul-Lager", "Er steht in einem Drachenmaul-Lager. Ihre Gruppen lassen sich leicht einzeln ziehen: Nehmt sie zuerst einzeln. Der Kampf selbst ist kurz, bisher ist nichts Besonderes aufgefallen." } }
T[61] = { note = "Er steht neben einem Ritualkreis in der Kanalisation, umgeben von Nekromanten des Kirin Tor.", { "Unheilige Raserei", "Seine Angriffe sind 20 Sekunden lang um 75 % schneller. Es ist Magie: Reinigen eines Schamanen oder Magie bannen eines Priesters entfernt den Effekt." }, { "Hauen", "Gelegentlich schlägt er mit einem Hieb zweimal zusätzlich zu, und Schlag erhöht den Schaden seines nächsten Treffers: Der Tank erleidet schwere Treffer." }, { "Totenerweckung", "Während des Kampfes erheben sich ständig Skelette rund um den Kreis. Sie sind schwach: Erledigt sie, sobald sie auftauchen." }, { "Entwaffnen", "Er entwaffnet den Tank für etwa 6 Sekunden." } }
T[62] = { { "Fokussierter Schlag", "Nach 3 Sekunden Zauberzeit geht 6 Sekunden lang ein Strahl vor ihm ab und trifft viermal pro Sekunde. Verlasst seinen Weg gleich zu Beginn des Zaubers." }, { "Arkanblitz", "Sein Angriff auf den Tank zwischen zwei Strahlen, 1,5 Sekunden Zauberzeit." } }
T[63] = { { "Manamorpher", "Verwandelt einen Spieler 8 Sekunden lang in ein Tier. Es ist Magie: Bannt sie." }, { "Stille", "Bringt 10 Sekunden lang zum Schweigen. Heiler, haltet Abstand." }, { "Arcane Manalings", "Er ruft ständig kleine Arcane Manalings herbei. Tötet sie mit Flächenschaden." } }
T[64] = { { "Fehlfunktion", "2 Sekunden Zauberzeit, dann trifft 6 Sekunden lang alle im Umkreis von 25 Metern alle 2 Sekunden arkane Energie für jeweils etwa 140 Schaden. Fernkämpfer, bleibt über 25 Meter entfernt; Nahkämpfer, geht während des Zaubers raus." }, { "Angry Tomes", "Angry Tomes stürmen auf dem Weg auf euch zu. Tötet sie, bevor ihr den Boss angreift." } }
T[65] = { { "Entkräften", "2 Sekunden Zauberzeit: Arkane Energie entzieht allen im Umkreis von 45 Metern bis zu 200 Mana." }, { "Vitalität entziehen", "Ein Magieeffekt auf den Tank: etwa 65 Arkanschaden alle 2 Sekunden über 10 Sekunden. Bannt ihn." }, { "Sein Raum", "Noch lebende Kreaturen in seinem Raum schließen sich dem Kampf an, wenn ihr ihn angreift. Räumt zuerst den Raum." } }
T[66] = { note = "Er wartet hinter einer magischen Barriere in der Stadtmitte, bewacht von Suffused Treants. Tötet die Treants und sprecht dann mit Magus Fansy Goodbringer, direkt südlich der Barriere: Er lässt sie fallen.", { "Teufelsholz", "Ranken schießen auf einen Spieler zu und treffen alle im Umkreis von 5 Metern um ihn, dann hinterlassen sie giftige Dämpfe am Boden. Verlasst die Dämpfe." }, { "Trampeln", "Er trampelt Spieler neben sich nieder und verursacht etwa 100 physischen Schaden." }, { "Umschlingen", "Verwurzelt bis zu zwei Spieler in seiner Nähe für einige Sekunden und schädigt sie über Zeit. Es ist Magie: Bannt sie." } }
T[67] = { note = "Sie ist am Anfang nicht da. Räumt in der Kanalisation nach Atrexis den Nordostraum, den mit den Marktständen und einem kleinen rosa Beschwörungskreis (nicht Atrexis' großer Kreis). Ein Spieler mit dem Tome of Dalaran klickt dann auf den Kreis, und Lyn kommt aus dem großen runden vergitterten Tor. Um das Buch zu bekommen, nehmt das Dunkle Buch vom Tisch im Raum von Erzmagier Arugal in der Burg Schattenfang, nachdem Arugal tot ist, und benutzt es am Leyline Focus, einem blauen Kristall in einem Hinterzimmer der Ambermill im Silberwald.", { "Schattenblitzsalve", "Schattenblitze auf alle im Umkreis von 30 Metern um sie." }, { "Dornenfluch", "1,5 Sekunden Zauberzeit: Ein 3-minütiger Fluch, der den Spieler gelegentlich verletzt, wenn er angreift. Entfernt ihn." }, { "Skelette", "Skelette erheben sich und kämpfen an ihrer Seite. Tötet sie." } }
T[68] = { note = "Erzmagierin Modera öffnet der Gruppe ein Portal zur purpurnen Kammer: Es führt zu ihm.", { "Begrenzendes Mana", "Eine Kugel rast auf einen zufälligen Spieler zu und kehrt dann zu ihm zurück. Alle, durch die sie fliegt, erleiden Arkanschaden und werden 6 Sekunden lang zum Schweigen gebracht: Stellt euch nicht zwischen ihn und diesen Spieler." }, { "Massenverwandlung", "Wenn ihm das Mana ausgeht, verwandelt er die ganze Gruppe 8 Sekunden lang in Tiere und kanalisiert dann 6 Sekunden lang Hervorrufung, um es aufzufüllen." }, { "Verlangsamen", "Verlangsamt 3 Sekunden lang alle um ihn herum: Angriffe und Zauber 30 % langsamer, Bewegung 70 % langsamer." }, { "Bleibt im Raum", "Verlässt während des Kampfes jemand den Raum, kehrt er mit voller Gesundheit zurück." } }
T[69] = { { "Netz", "Hält alle in seiner Nähe 10 Sekunden lang fest." }, { "Verlangsamen", "Verlangsamt Angriffe und Bewegung eines Spielers für 10 Sekunden und kann ihn betäuben." }, { "Mechanische Schabe beschwören", "Ruft mechanische Schaben. Sein Update tötet sie und heilt ihn." } }
T[70] = { note = "Sprich mit Sprengmeisterin Emi Shortfuse und beschütze sie, während sie die beiden Höhleneingänge sprengt. Troggs kommen in Wellen, dann erscheint Grubbis mit Chomper." }
T[71] = { { "Megavolt", "Naturschaden in einem Kegel vor ihm (2 Sekunden Zauberzeit). Nur der Tank steht davor." }, { "Kettenblitzschlag", "Ein Blitz, der auf Spieler in der Nähe überspringt (2,5 Sekunden Zauberzeit). Unterbrich ihn." } }
T[72] = { { "Niedermähen", "Trifft alle in seiner Nähe und unterbricht ihre Zauber. Zauberer und Heiler, haltet Abstand." }, { "Kegelförmiger Schlag", "Trifft alle in einem Kegel vor ihm." }, { "Zertrampeln", "Trifft alle, die in seiner Nähe stehen." } }
T[73] = { { "Flammendiener beschwören", "Ruft zu Beginn des Kampfes zwei Flammendiener." }, { "Feuerball", "Er hält Abstand, um ihn zu wirken. Unterbrich ihn." }, { "Feuerschild II", "Feuerschaden an allen in seiner Nähe für eine Minute. Ein Priester oder Schamane kann es entfernen." } }
T[74] = { { "Laufende Bomben", "Er entzündet nacheinander die Gnomenköpfe rund um den Raum, und jeder lässt laufende Bomben los, die beim Erreichen eines Spielers explodieren. Der Knopf neben einem Kopf schaltet ihn aus. Unter der Hälfte seines Lebens entzündet er sie schneller." }, { "Wegstoßen", "Stößt den Tank weg. Unter der Hälfte seines Lebens trifft es alle um ihn herum." } }
T[75] = { { "Ebergeist beschwören", "Ruft alle 30 bis 45 Sekunden einen Ebergeist an seine Seite (1,5 Sekunden Zauberzeit). Tötet jeden, bevor der nächste kommt." }, { "Kettenheilung", "Unter 75 % Gesundheit heilt er sich, und die Heilung springt auf zwei nahe Verbündete über (2,5 Sekunden Zauberzeit). Unterbrecht ihn." } }
T[76] = { { "Gedanken beherrschen", "Übernimmt 15 Sekunden lang die Kontrolle über einen Spieler, der nicht sein Ziel ist (2 Sekunden Zauberzeit). Unterbrecht ihn oder bannt den Effekt vom Spieler." }, { "Schattenblitz", "Er hält Abstand, um ihn zu wirken. Unterbrecht ihn." } }
T[77] = { { "Ruft um Hilfe", "Wenn ihr ihn angreift, ruft er Kreaturen im Umkreis von 15 Metern herbei, darunter die beiden Wächter der Klingenhauer an seiner Seite. Haltet im Kampf einen der beiden unter Kontrolle." }, { "Donnerknall", "Alle 8 bis 14 Sekunden: Naturschaden an allen in seiner Nähe, und ihre Angriffe und Bewegungen werden 10 Sekunden lang verlangsamt." } }
T[78] = { { "Wirbelndes Sperrfeuer", "Trifft alle, die in seiner Nähe stehen." }, { "Dornen-Aura", "Jeder, der ihn oder einen nahen Verbündeten (Oberanführer Rammhauer eingeschlossen) trifft, erleidet Naturschaden." } }
T[79] = { note = "Ein Schutz versiegelt seine Höhle. Tötet die beiden Totenschädelwächter davor: Er fällt, wenn beide tot sind.", { "Totgeglaubt zurückgelassen", "Alle 21 bis 35 Sekunden schlägt er einen Spieler, der nicht sein Ziel ist; dieser fällt wie tot um und kann weder angreifen noch zaubern. Bewegen beendet den Effekt." }, { "Toben", "Alle 25 bis 31 Sekunden: Trifft alle in seiner Nähe und betäubt sie 2,5 Sekunden lang." }, { "Wutanfall", "Bei 60 % Gesundheit und dann bei 40 % greift er 2 Minuten lang 60 % schneller an und schlägt härter zu." } }
T[80] = { note = "Eine seltene Fledermaus: Sie ist nicht bei jedem Durchgang da. Wenn sie da ist, wartet sie in einer kleinen Nische der Wand der Fledermaushöhle, nahe Charlga Razorflank." }
T[81] = { { "Kettenblitzschlag", "Sie hält Abstand und wirkt ihn immer wieder: Ein Blitz, der auf bis zu 3 Spieler überspringt (2,5 Sekunden Zauberzeit). Unterbrecht ihn." }, { "Reinheit", "Alle 9 bis 15 Sekunden ist sie 2 Sekunden lang immun gegen alle Angriffe und Zauber." }, { "Erneuerung", "Heilt einen verwundeten Verbündeten oder sich selbst über 15 Sekunden. Ein Priester oder Schamane kann den Effekt entfernen." } }
T[82] = { { "Erdenrumpler beschwören", "Ein Steinrumpler begleitet ihn und kämpft an seiner Seite." }, { "Blitzschlag", "Er hält Abstand, um ihn zu wirken. Unterbrecht ihn." }, { "Flieht um Hilfe", "Bei 15 % Gesundheit flieht er, um Hilfe zu holen. Erledigt ihn, bevor er entkommt." } }
T[83] = { { "Erdenrumpler beschwören", "Ein Steinrumpler begleitet ihn und kämpft an seiner Seite." }, { "Blitzschlag", "Er hält Abstand, um ihn zu wirken. Unterbrecht ihn." } }
T[84] = { { "Schattenwort: Schmerz", "Schattenschaden auf sein Ziel alle 3 Sekunden über 18 Sekunden. Magie bannen entfernt ihn." } }
T[85] = { note = "Etwa in jedem dritten Durchgang steht einer der drei Seltenen des Friedhofs an einem von sechs Orten auf der Karte: Azshir the Sleepless, Fallen Champion oder Ironspine.", { "Ruf des Grabes", "Nach 60 Sekunden Schattenschaden am Spieler (2 Sekunden Zauberzeit). Ein Magier oder Druide kann ihn vorher entfernen." }, { "Erschrecken", "Lässt einen Spieler 4 Sekunden lang in Furcht fliehen." }, { "Seelen-Siphon", "Unter halber Gesundheit entzieht er einem Spieler und dem ihm nächsten Spieler 12 Sekunden lang Leben und heilt sich selbst." } }
T[86] = { note = "Etwa in jedem dritten Durchgang steht einer der drei Seltenen des Friedhofs an einem von sechs Orten auf der Karte: Azshir the Sleepless, Fallen Champion oder Ironspine.", { "Spalten", "Trifft sein Ziel und den Spieler, der ihm am nächsten ist." }, { "Hinrichten", "Trifft ein Ziel mit 20 % Gesundheit oder weniger hart. Haltet den Tank darüber." } }
T[87] = { note = "Etwa in jedem dritten Durchgang steht einer der drei Seltenen des Friedhofs an einem von sechs Orten auf der Karte: Azshir the Sleepless, Fallen Champion oder Ironspine.", { "Fluch der Schwäche", "Verringert 2 Minuten lang den physischen Schaden aller im Umkreis von 30 Metern. Ein Magier oder Druide kann ihn entfernen." }, { "Giftwolke", "Naturschaden alle 5 Sekunden über 45 Sekunden an allen in der Nähe." } }
T[88] = { { "Flammenstachel", "Eine Flammensäule dort, wo ein Spieler steht (3 Sekunden Zauberzeit): Feuerschaden, dann alle 3 Sekunden erneut über 9 Sekunden. Geht heraus." }, { "Feuernova", "Feuerschaden an allen im Umkreis von 10 Metern um ihn." }, { "Flammenschock", "Feuerschaden an einem Spieler, dann alle 3 Sekunden erneut über 12 Sekunden. Magie bannen entfernt ihn." }, { "Schattenblitz", "Er hält Abstand, um ihn zu wirken. Unterbrecht ihn." } }
T[89] = { { "Scharlachrote Jagdhunde", "Drei Hunde begleiten ihn und greifen mit ihm an, und er gibt ihnen auch Kampfrausch. Tötet sie zuerst." }, { "Kampfrausch", "Beschleunigt seine Angriffe oder die eines Verbündeten 30 Sekunden lang um 30 %. Ein Priester oder Schamane kann ihn entfernen." }, { "Schlachtruf", "Mehr Angriffskraft für ihn und seine Hunde für 3 Minuten." } }
T[90] = { { "Detonation", "Bei halber Gesundheit schließt er sich 8 Sekunden lang in einer Arkanblase ein und wirkt Detonation (5 Sekunden Zauberzeit): schwerer Feuerschaden an allen im Umkreis von 30 Metern. Verlasst die Reichweite vor der Explosion und kehrt dann zurück." }, { "Verwandlung", "Verwandelt einen Spieler, der nicht sein Ziel ist, bis zu 20 Sekunden lang in ein Schaf (1,5 Sekunden Zauberzeit). Unterbrecht ihn oder bannt den Effekt vom Spieler." }, { "Stille", "Bringt alle im Umkreis von 15 Metern 10 Sekunden lang zum Schweigen (1,5 Sekunden Zauberzeit). Wenn ihr heilt, bleibt weiter weg." }, { "Arkane Explosion", "Alle paar Sekunden Arkanschaden an allen im Umkreis von 10 Metern. Fernkämpfer, haltet Abstand." } }
T[91] = { { "Wirbelwind", "Alle 15 bis 25 Sekunden wirbelt er 10 Sekunden lang und trifft alle in seiner Nähe. Als Nahkämpfer geht zurück, bis es endet." }, { "Spalten", "Trifft sein Ziel und den Spieler, der ihm am nächsten ist." }, { "Wutanfall", "Bei 30 % Gesundheit greift er 2 Minuten lang 60 % schneller an und schlägt härter zu." }, { "Scharlachrote Rekruten", "Wenn er stirbt, kommen 20 Scharlachrote Rekruten durch die Tür des Raums und greifen an. Bleibt bei eurer Gruppe und nutzt Flächenschaden." } }
T[92] = { { "Fluch von Tuten'kash", "Fluch, der die Zaubergeschwindigkeit nahe stehender Spieler um 15 % senkt und ihre Angriffe um 18 % verlangsamt, 15 Minuten lang. Entferne den Fluch." } }
T[93] = { { "Feuerball", "Ein Feuerball auf sein Ziel, immer wieder. Unterbrich ihn." }, { "Feuernova", "Feuerschaden an allen Spielern in seiner Nähe. Geh weg, wenn er es wirkt." } }
T[94] = { { "Krankheitswolke", "Eine Krankheitswolke um ihn verletzt alle Spieler in der Nähe alle 3 Sekunden. Kämpfe auf Distanz oder entferne die Krankheit." }, { "Wutanfall", "Er wird wütend und erhöht 2 Minuten lang Schaden und Angriffstempo. Heile den Tank stärker." } }
T[95] = { { "Gedanken beherrschen", "Kontrolliert einen Spieler 10 Sekunden lang. Banne den Effekt und verhindere, dass der Kontrollierte der Gruppe schadet." }, { "Schattenwort: Schmerz", "Schattenschaden alle 3 Sekunden für 18 Sekunden. Banne ihn." }, { "Heilen", "Heilt sich oder einen Verbündeten. Unterbrich den Zauber." }, { "Schattenblitz", "Blitz mit Schattenschaden auf ein Ziel, 3 Sekunden Zauberzeit. Unterbrich ihn." } }
T[96] = { { "Amnennars Zorn", "Schleudert ein Ziel zurück. Geh wieder in Position." }, { "Frostblitz", "Ein Frostblitz, der sein Ziel verlangsamt, immer wieder. Unterbrich ihn." }, { "Frostnova", "Frostschaden und Verwurzelung aller Spieler in seiner Nähe. Banne die Wurzel." } }
T[97] = { { "Welkberührung", "Krankheit, die alle 10 Sekunden 3 Minuten lang Schattenschaden verursacht und Mana entzieht, das er erhält. Heile sie, vor allem bei Zauberwirkern." }, { "Eitriger Gestank", "Senkt Stärke und Beweglichkeit von Spielern in der Nähe um 50 für 10 Sekunden und verhindert das Zaubern. Zauberwirker, haltet Abstand zu ihm." } }
T[98] = { note = "Er liegt wie tot auf dem Boden in der kleinen Kammer neben dem Altar und steht auf, wenn man ihn angreift.", { "Furcht", "Lässt einen Spieler bis zu 8 Sekunden lang vor Schrecken fliehen (1,5 Sekunden Zauberzeit). Unterbrecht ihn." }, { "Schlaf", "Versetzt alle in seiner Nähe bis zu 10 Sekunden lang in Schlaf. Schaden weckt einen Schläfer auf." }, { "Blutfluch", "Ein Spieler erleidet 10 Minuten lang mehr physischen Schaden (2 Sekunden Zauberzeit). Ein Magier oder Druide kann ihn entfernen." }, { "Heilen", "Bei 30 % Gesundheit heilt er sich (3 Sekunden Zauberzeit). Unterbrecht ihn." } }
T[99] = { { "Ruft um Hilfe", "Wenn ihr ihn angreift, ruft er alle Scharlachroten Verteidiger im Umkreis von 80 Metern herbei. Räumt die Kathedrale, bevor ihr ihn angreift." }, { "Hammer der Gerechtigkeit", "Betäubt einen Spieler 5 Sekunden lang." }, { "Gottesschild", "Bei halber Gesundheit wird er 12 Sekunden lang immun gegen allen Schaden und alle Zauber." }, { "Aura der Vergeltung", "Heiligschaden für jeden, der ihn im Nahkampf trifft." } }
T[100] = { note = "Wenn Mograine fällt, stellt er sich nur tot: Sie kommt aus dem Raum hinter dem Altar und greift an.", { "Scharlachrot-Auferstehung", "Bei halber Gesundheit versetzt sie den ganzen Raum bis zu 10 Sekunden lang in Schlaf, rennt zu Mograine und erweckt ihn wieder. Er stellt mit Handauflegen ihre gesamte Gesundheit wieder her, und die beiden kämpfen gemeinsam gegen euch." }, { "Heiliges Schmettern", "Heiligschaden an ihrem Ziel (2,5 Sekunden Zauberzeit). Unterbrecht sie." }, { "Heilen", "Heilt den am schwersten verwundeten ihrer Verbündeten, Mograine eingeschlossen (3 Sekunden Zauberzeit). Unterbrecht sie." }, { "Machtwort: Schild", "Schützt sie bis zu 30 Sekunden lang vor Schaden. Ein Priester oder Schamane kann ihn entfernen." } }
T[101] = { { "Sturmattacke", "Erhöht sein Lauftempo für 3 Sekunden und fügt seinem ersten Angriff zusätzlichen Schaden hinzu. Heile den Getroffenen." } }
T[102] = { { "Schlag", "Ein verstärkter Nahkampfschlag auf sein Ziel. Heile den Tank." } }
T[103] = { { "Schildschlag", "Schlägt sein Ziel und betäubt es 2 Sekunden lang. Heile während der Betäubung." } }
T[104] = { { "Blitzschlag", "Ein Naturblitz auf sein Ziel. Unterbrich ihn." }, { "Kettenblitzschlag", "Naturblitz, der auf bis zu 3 Spieler überspringt. Unterbrich ihn und verteilt euch." } }
